cd ciframe && python - <<'PY'
import marshal, pathlib
for p in pathlib.Path('tests/__pycache__').glob('test_regressao_legado*.pyc'):
    print('====', p)
    with open(p,'rb') as f:
        f.read(16); code=marshal.load(f)
    def walk(c, depth=0):
        print('  '*depth, c.co_name)
        for const in c.co_consts:
            if hasattr(const,'co_name'): walk(const, depth+1)
    walk(code)
    break
PY

content.text:
.bug {
  border: solid 1px red;
}
body {
  overflow-x: hidden;
  font-family: 'Varela Round', sans-serif;
}
.top {
  position: absolute;
  width: 100%;
  z-index: 100;
}
.top ul {
  float: right;
  padding-top: 10px;
}
@keyframes slideInRight {
    from    { transform:translateX(100%); }
    to      { transform: translateX(0); }
}
@keyframes slideInLeft {
    from    { transform:translateX(0); }
    to      { transform: translateX(-100%); }
}
.page {
  position: absolute;
  width: 100%;
  height: 100%;
  transition: all 1s ease;
  -webkit-transition:all 1s ease;
  -moz-transition: all 1s ease;
  -o-transition: all 1s ease;
}
.page.ng-enter {
    animation: slideInRight .5s both ease-in-out;
}
.page.ng-leave {
    animation: slideInLeft .5s both ease-in-out;
}
.navbar-brand > svg {
  width: 200px;
}
.logo-d,
.logo-e1,
.logo-c,
.logo-i,
.logo-dot1,
.logo-f,
.logo-r,
.logo-a,
.logo-dot,
.logo-m,
.logo-e { fill:#FFF; }

.logo-d-color,
.logo-e1-color { fill:#791459; }
.logo-c-color,
.logo-i-color,
.logo-dot1-color,
.logo-f-color,
.logo-r-color,
.logo-a-color { fill:#9C0A5D; }
.logo-dot-color,
.logo-m-color,
.logo-e-color { fill:#791459; }
.vertical-img-wrapper {
  line-height: 500px;
}
.viewWindow-panel {
  overflow: auto;
}
@media (min-width: 768px) {
  .viewWindow-panel {
    height: 100vh;
  }
}
.viewWindow-panel-A { background:#372478; color: #FFFFFF; } .viewWindow-panel-container h4:first-child { margin-top: 40px; margin-bottom: 60px;}
.viewWindow-panel-B { background:#7B057E; color: #FFFFFF; }
.viewWindow-panel-C { background:#BA007C; color: #FFFFFF; }
.viewWindow-panel-D { background:#FFFFFF; color: #333333; }
.viewWindow-panel-E { background:#E9BC00; color: #FFFFFF; overflow: hidden; }
.viewWindow-panel-F {
  background:#BA007C; color: #FFFFFF
  background: -moz-linear-gradient(top, #372478 0%, #372478 50%, #BA007C 51%, #BA007C 100%, #BA007C 100%);
  background: -webkit-linear-gradient(top, #372478 0%, #372478 50%,#BA007C 51%,#BA007C 100%,#BA007C 100%);
  background: linear-gradient(to bottom, #372478 0%, #372478 50%,#BA007C 51%,#BA007C 100%,#BA007C 100%);
}
.viewWindow-panel-D a:link,
.viewWindow-panel-D a:visited {
  display: block;
  font-size: 1.2em;
  line-height: 1.1em;
  padding: 10px;
  border-radius: 4px;
  background-color: #eee;
  text-decoration: none;
  color: #333;
}
.viewWindow-panel-D a:active,
.viewWindow-panel-D a:hover {
  background-color: #E9BC00;
  text-decoration: none;
}
.viewWindow-panel-D a > small {
  font-size: 0.8em;
}
