/* ============================================================
   DECIFRA-ME — Página #/porsequencia (layout Flexbox)
   ============================================================ */

.decifra-page {
  display: flex;
  width: 100%;
  min-height: 100vh;
  overflow-x: hidden;
}

/* Sidebar esquerda — magenta, aproximadamente 33% */
.decifra-sidebar {
  flex: 0 0 33.333%;
  min-width: 260px;
  max-width: 400px;
  background-color: #BA007C;
  color: #FFFFFF;
  padding: 48px 24px 24px;
  box-sizing: border-box;
  overflow-y: auto;
}

.sidebar-logo {
  font-family: 'Varela Round', sans-serif;
  font-size: 28px;
  font-weight: bold;
  text-align: center;
  color: #FFFFFF;
  margin-bottom: 30px;
  letter-spacing: 1px;
}

.decifra-sidebar h3.sidebar-title {
  text-align: center;
  margin: 0 0 24px;
  font-size: 20px;
  color: #FFFFFF;
}

.decifra-sidebar h4.text-center {
  margin-bottom: 24px;
}

/* Contêiner dos grupos de acordes */
.chord-groups {

.chord-groups {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
}

/* Grupo de uma sequência (linha de hexágonos) */
.chord-group {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

/* Sequências customizadas (comunidade) — fundo lilás discreto */
.sequencia-customizada {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  padding: 6px;
  margin: 4px 0;
}

.sequencia-label {
  font-size: 0.75em;
  color: #FFFFFF;
  margin-top: 4px;
  text-align: center;
  opacity: 0.9;
}
.sequencia-label .glyphicon {
  color: #FFFFFF;
}

/* Conteúdo principal direito — branco, aproximadamente 67% */
.decifra-main {
  flex: 1;
  min-width: 0;
  padding: 24px;
  background-color: #FFFFFF;
  box-sizing: border-box;
  overflow-y: auto;
}

/* Painel de cadastro — lilás claro, topo da área principal */
.registration-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  padding: 24px;
  margin-bottom: 28px;
  box-sizing: border-box;
  background-color: #f1e5fc;
  border: 1px solid #d1c4e9;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.registration-description {
  display: flex;
  align-items: center;
  gap: 18px;
}

.registration-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 62px;
  height: 62px;
  flex-shrink: 0;
  background-color: #BA007C;
  color: #FFFFFF;
  border-radius: 50%;
  font-size: 36px;
  line-height: 1;
}

.registration-description h2 {
  font-size: 19px;
  margin: 0 0 8px;
  color: #333;
}

.registration-description p {
  font-size: 13px;
  margin: 0;
  color: #555;
}

/* Formulário horizontal (telas grandes) */
.registration-form {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  flex-wrap: wrap;
}

.form-field {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  gap: 8px;
}

.form-field label {
  font-size: 14px;
  font-weight: 600;
  color: #333;
}

.form-field input {
  width: 100%;
  height: 48px;
  padding: 0 12px;
  box-sizing: border-box;
  border: 1px solid #cbb8df;
  border-radius: 9px;
  background: #FFFFFF;
  color: #333;
  font-size: 14px;
  font-family: 'Varela Round', sans-serif;
}

.btn-register {
  height: 48px;
  padding: 0 22px;
  flex-shrink: 0;
  background-color: #BA007C;
  color: #FFFFFF;
  border: none;
  border-radius: 9px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  font-family: 'Varela Round', sans-serif;
  font-size: 14px;
}

.btn-register:hover {
  background-color: #920069;
}

/* Alertas */
.alert-erro {
  color: #a94442;
  background: #f2dede;
  border: 1px solid #ebccd1;
  border-radius: 6px;
  padding: 10px 14px;
  margin-top: 8px;
  font-size: 0.9em;
}

.alert-sucesso {
  color: #3c763d;
  background: #dff0d8;
  border: 1px solid #d6e9c6;
  border-radius: 6px;
  padding: 10px 14px;
  margin-top: 8px;
  font-size: 0.9em;
}

/* Seção de busca */
.search-section {
  margin-bottom: 24px;
}

.search-title {
  font-size: 18px;
  margin: 0 0 16px;
  color: #333;
}

.search-controls {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 8px;
  flex-wrap: wrap;
}

.selected-sequence {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

/* Resultados — cards de música */
.music-card {
  background-color: #EDEEEF;
  color: #3C3B3C;
  padding: 10px;
  margin-top: 5px;
  margin-bottom: 5px;
  border-radius: 4px;
  min-height: 150px;
  cursor: pointer;
}

/* ============================================================
   Responsividade
   ============================================================ */

@media (max-width: 1100px) {
  .registration-panel {
    flex-direction: column;
    align-items: stretch;
  }

  .registration-form {
    flex-wrap: wrap;
  }
}

@media (max-width: 768px) {
  .decifra-page {
    flex-direction: column;
  }

  .decifra-sidebar {
    flex: none;
    width: 100%;
    max-width: 100%;
    min-width: auto;
  }

  .decifra-main {
    width: 100%;
    padding: 16px;
  }

  .registration-form {
    flex-direction: column;
    align-items: stretch;
  }

  .btn-register {
    width: 100%;
  }

  .search-controls {
    flex-wrap: wrap;
  }

  .music-results {
    grid-template-columns: 1fr;
  }
}

/* Manter classes legacy do Bootstrap para outras páginas */
.form-control-inverse {
  color: #333;
}


