# coding: utf-8
"""Catálogo de sequências de acordes famosas.

Concentra três responsabilidades coesas:

- canonicalização de acordes/sequências (normalização e chave estável);
- a regra pura de matching para sequências novas (run contíguo com dedup);
- persistência do catálogo em SQLite (as 6 sequências legadas são semeadas de
  forma idempotente).

As músicas e gêneros continuam vindo do CSV em memória; este módulo só persiste
o catálogo de sequências.
"""
import json
import os
import re
import sqlite3
import unicodedata
from contextlib import closing
from datetime import datetime, timezone

DB_ENV = 'DECIFRAME_DB_PATH'
DEFAULT_DB_PATH = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), 'instance', 'deciframe.db')

MIN_ACORDES = 2
MAX_ACORDES = 12
MAX_ACORDES_BRUTOS = 64
MAX_TAM_ACORDE = 16
MAX_TAM_NOME = 80

# As 6 sequências que existiam hardcoded em main.py. O legado_id é o valor usado
# na coluna SEQ_FAMOSA do CSV; é ele que garante o resultado de busca original.
LEGACY_SEQUENCES = (
    (0, ['Bm', 'G', 'D', 'A']),
    (1, ['C', 'G', 'Am', 'F']),
    (2, ['Em', 'G']),
    (3, ['C', 'A7', 'Dm', 'G7']),
    (4, ['Gm', 'F']),
    (5, ['C', 'C7', 'F', 'Fm']),
)

# Fundamental (A-G), acidente opcional (#/b) e sufixo livre usado pelo dataset
# (m, 7, 9, 4/7, (7/9), /D, 5-, +, etc.). O '|' da chave fica de fora.
_ACORDE_RE = re.compile(r'^[A-Ga-g][#b]?[A-Za-z0-9#b+\-/()]*$')


class SequenciaDuplicada(Exception):
    def __init__(self, existente):
        super(SequenciaDuplicada, self).__init__('sequencia ja cadastrada')
        self.existente = existente


def _chave_acorde(acorde):
    """Chave de comparação: sem espaços, unicode normalizado, case-insensitive."""
    return unicodedata.normalize('NFKC', acorde).strip().casefold()


def normalizar_acorde(acorde):
    """Valida e devolve a forma de exibição do acorde.

    A fundamental recebe maiúscula (``am`` -> ``Am``); o restante é preservado
    (``C#m``, ``Bb9``, ``Dm4/7``).
    """
    if not isinstance(acorde, str):
        raise ValueError('cada acorde deve ser texto')
    valor = ' '.join(unicodedata.normalize('NFKC', acorde).split())
    if not valor:
        raise ValueError('acorde vazio')
    if len(valor) > MAX_TAM_ACORDE:
        raise ValueError('acorde muito longo: %s' % valor)
    if not _ACORDE_RE.match(valor):
        raise ValueError('acorde invalido: %s' % valor)
    return valor[0].upper() + valor[1:]


def _colapsar_repetidos(valores):
    colapsados = []
    for valor in valores:
        if not colapsados or colapsados[-1] != valor:
            colapsados.append(valor)
    return colapsados


def canonicalizar_acordes(acordes):
    """Valida, normaliza e colapsa repetições consecutivas.

    ``['C', 'C', 'G', 'G', 'Am']`` vira ``['C', 'G', 'Am']``: repetir o mesmo
    acorde não muda a progressão e não deve criar uma sequência "diferente".
    """
    if not isinstance(acordes, (list, tuple)):
        raise ValueError('acordes deve ser uma lista')
    if len(acordes) > MAX_ACORDES_BRUTOS:
        raise ValueError('acordes demais')
    normalizados = [normalizar_acorde(a) for a in acordes]
    chaves = _colapsar_repetidos([_chave_acorde(a) for a in normalizados])
    if len(chaves) < MIN_ACORDES:
        raise ValueError('informe ao menos %d acordes' % MIN_ACORDES)
    if len(chaves) > MAX_ACORDES:
        raise ValueError('informe no maximo %d acordes' % MAX_ACORDES)

    colapsados = []
    for acorde in normalizados:
        if not colapsados or _chave_acorde(colapsados[-1]) != _chave_acorde(acorde):
            colapsados.append(acorde)
    return colapsados


def chave_sequencia(acordes):
    """Chave canônica estável usada para deduplicar e buscar."""
    return '|'.join(_chave_acorde(a) for a in acordes)


def nome_padrao(acordes):
    return ' - '.join(acordes)


def cifra_contem_sequencia(cifra, acordes):
    """True se ``acordes`` ocorre como run contíguo em ``cifra``.

    Comparação case-insensitive, com repetições consecutivas colapsadas nos dois
    lados. Ordem importa; um acorde intermediário quebra o match.
    """
    if not cifra or not acordes:
        return False
    alvo = _colapsar_repetidos([_chave_acorde(a) for a in acordes])
    if not alvo:
        return False
    musica = _colapsar_repetidos([_chave_acorde(c) for c in cifra])
    n = len(alvo)
    if n > len(musica):
        return False
    for i in range(len(musica) - n + 1):
        if musica[i:i + n] == alvo:
            return True
    return False


def _legado_por_concatenado():
    tabela = {}
    for _, acordes in LEGACY_SEQUENCES:
        tabela[''.join(_chave_acorde(a) for a in acordes)] = acordes
    return tabela


_LEGADO_POR_CONCATENADO = _legado_por_concatenado()


def resolver_parametro(valor):
    """Resolve o parâmetro ``sequencia`` para uma sequência do catálogo.

    Aceita o formato atual do frontend (``C,G,Am,F``) e o formato concatenado
    das 6 originais (``CGAmF``), mantendo compatibilidade com clientes antigos.
    Devolve ``None`` quando não encontra (o endpoint responde ``[]``).
    """
    if not valor:
        return None
    if ',' in valor:
        partes = [p for p in valor.split(',') if p.strip()]
        if not partes:
            return None
        try:
            acordes = canonicalizar_acordes(partes)
        except ValueError:
            return None
        return buscar_por_chave(chave_sequencia(acordes))

    acordes_legados = _LEGADO_POR_CONCATENADO.get(_chave_acorde(valor))
    if acordes_legados is None:
        return None
    return buscar_por_chave(chave_sequencia(acordes_legados))


# --------------------------------------------------------------------------
# Persistência
# --------------------------------------------------------------------------

_SCHEMA = '''
CREATE TABLE IF NOT EXISTS sequencias (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT NOT NULL,
    acordes TEXT NOT NULL,
    chave TEXT NOT NULL UNIQUE,
    legado_id INTEGER UNIQUE,
    criada_em TEXT NOT NULL
);
'''


def caminho_db():
    return os.environ.get(DB_ENV) or DEFAULT_DB_PATH


def conectar():
    caminho = caminho_db()
    diretorio = os.path.dirname(os.path.abspath(caminho))
    if diretorio:
        os.makedirs(diretorio, exist_ok=True)
    conn = sqlite3.connect(caminho, timeout=5)
    conn.row_factory = sqlite3.Row
    conn.execute('PRAGMA journal_mode=WAL')
    conn.execute('PRAGMA busy_timeout=5000')
    return conn


def _agora_iso():
    agora = datetime.now(timezone.utc).replace(microsecond=0)
    return agora.isoformat().replace('+00:00', 'Z')


def _row_para_interno(row):
    if row is None:
        return None
    return {
        'id': row['id'],
        'nome': row['nome'],
        'acordes': json.loads(row['acordes']),
        'chave': row['chave'],
        'legado_id': row['legado_id'],
        'criada_em': row['criada_em'],
    }


def publica(sequencia):
    """Formato público (sem detalhes internos de persistência)."""
    return {
        'id': sequencia['id'],
        'nome': sequencia['nome'],
        'acordes': sequencia['acordes'],
        'legado': sequencia['legado_id'] is not None,
        'criada_em': sequencia['criada_em'],
    }


def _semear(conn):
    for legado_id, acordes in LEGACY_SEQUENCES:
        conn.execute(
            'INSERT OR IGNORE INTO sequencias '
            '(nome, acordes, chave, legado_id, criada_em) VALUES (?, ?, ?, ?, ?)',
            (nome_padrao(acordes),
             json.dumps(acordes, ensure_ascii=False),
             chave_sequencia(acordes),
             legado_id,
             _agora_iso()))


def init_db():
    """Cria o schema e semeia as 6 legadas de forma idempotente."""
    with closing(conectar()) as conn, conn:
        conn.executescript(_SCHEMA)
        _semear(conn)


def listar_sequencias():
    with closing(conectar()) as conn:
        rows = conn.execute('SELECT * FROM sequencias ORDER BY id').fetchall()
    return [publica(_row_para_interno(r)) for r in rows]


def buscar_por_chave(chave):
    with closing(conectar()) as conn:
        row = conn.execute(
            'SELECT * FROM sequencias WHERE chave = ?', (chave,)).fetchone()
    return _row_para_interno(row)


def inserir_sequencia(acordes, nome=None):
    """Cadastra uma sequência nova ou levanta ``SequenciaDuplicada``."""
    acordes = canonicalizar_acordes(acordes)
    if nome is not None and not isinstance(nome, str):
        raise ValueError('nome deve ser texto')
    nome_final = ' '.join((nome or '').split()) or nome_padrao(acordes)
    if len(nome_final) > MAX_TAM_NOME:
        raise ValueError('nome muito longo')
    chave = chave_sequencia(acordes)

    existente = buscar_por_chave(chave)
    if existente is not None:
        raise SequenciaDuplicada(existente)

    try:
        with closing(conectar()) as conn, conn:
            conn.execute(
                'INSERT INTO sequencias '
                '(nome, acordes, chave, legado_id, criada_em) VALUES (?, ?, ?, NULL, ?)',
                (nome_final, json.dumps(acordes, ensure_ascii=False),
                 chave, _agora_iso()))
    except sqlite3.IntegrityError:
        # Corrida entre dois cadastros iguais: o UNIQUE resolve.
        existente = buscar_por_chave(chave)
        if existente is not None:
            raise SequenciaDuplicada(existente)
        raise

    return buscar_por_chave(chave)

